SELECT 'printings' AS scope,id::text AS identity,to_jsonb(t) AS payload FROM catalog.card_printings t WHERE id=ANY(ARRAY['d70868de-b7dc-414e-ac9f-d63055956ef0']::uuid[]) UNION ALL SELECT 'variants',id::text,to_jsonb(t) FROM catalog.card_variants t WHERE printing_id=ANY(ARRAY['d70868de-b7dc-414e-ac9f-d63055956ef0']::uuid[]) UNION ALL SELECT 'names',id::text,to_jsonb(t) FROM catalog.card_names t WHERE printing_id=ANY(ARRAY['d70868de-b7dc-414e-ac9f-d63055956ef0']::uuid[]) OR variant_id=ANY(ARRAY['a5401eba-11c3-42f1-a05e-f76b3db9d945']::uuid[]) UNION ALL SELECT 'sets',id::text,to_jsonb(t) FROM catalog.sets t WHERE id=ANY(ARRAY['6bbc266c-3ebc-4f6e-a3a5-d8a6d40427b7']::uuid[]) UNION ALL SELECT 'sources',id::text,to_jsonb(t) FROM ingest.sources t WHERE (code IN ('scrydex','pokellector','tcgcollector','pricecharting') OR lower(base_url) LIKE '%pokellector.com%' OR lower(base_url) LIKE '%tcgcollector.com%' OR lower(base_url) LIKE '%pricecharting.com%') UNION ALL SELECT 'assets',id::text,to_jsonb(t) FROM catalog.assets t WHERE printing_id=ANY(ARRAY['d70868de-b7dc-414e-ac9f-d63055956ef0']::uuid[]) OR variant_id=ANY(ARRAY['a5401eba-11c3-42f1-a05e-f76b3db9d945']::uuid[]) OR (printing_id IS NULL AND variant_id IS NULL AND set_id=ANY(ARRAY['6bbc266c-3ebc-4f6e-a3a5-d8a6d40427b7']::uuid[])) UNION ALL SELECT 'links',catalogue_version_id::text||':'||asset_id::text,to_jsonb(t) FROM catalog.catalogue_version_assets t WHERE printing_id=ANY(ARRAY['d70868de-b7dc-414e-ac9f-d63055956ef0']::uuid[]) OR variant_id=ANY(ARRAY['a5401eba-11c3-42f1-a05e-f76b3db9d945']::uuid[]) OR asset_id IN(SELECT id FROM catalog.assets WHERE printing_id=ANY(ARRAY['d70868de-b7dc-414e-ac9f-d63055956ef0']::uuid[]) OR variant_id=ANY(ARRAY['a5401eba-11c3-42f1-a05e-f76b3db9d945']::uuid[]) OR (printing_id IS NULL AND variant_id IS NULL AND set_id=ANY(ARRAY['6bbc266c-3ebc-4f6e-a3a5-d8a6d40427b7']::uuid[]))) OR(printing_id IS NULL AND variant_id IS NULL AND set_id=ANY(ARRAY['6bbc266c-3ebc-4f6e-a3a5-d8a6d40427b7']::uuid[])) ORDER BY scope,identity;
